<?php
use Illuminate\Support\Facades\Route;
Route::prefix('api/v1/savings')->middleware(['auth:sanctum','ensure.addon:savings.goals'])->group(function(){ Route::get('/', [\Semizzy\Addons\Savings\Http\Controllers\SavingsController::class,'apiIndex'])->middleware('permission:savings.view'); Route::post('/goals', [\Semizzy\Addons\Savings\Http\Controllers\SavingsController::class,'create'])->middleware(['permission:savings.create','transaction.pin','throttle:10,1']); Route::post('/{reference}/contribute', [\Semizzy\Addons\Savings\Http\Controllers\SavingsController::class,'contribute'])->middleware(['permission:savings.create','transaction.pin','throttle:10,1']); Route::post('/{reference}/withdraw', [\Semizzy\Addons\Savings\Http\Controllers\SavingsController::class,'withdraw'])->middleware(['permission:savings.withdraw','transaction.pin','throttle:5,1']); });